parameters.jsCode:
// Extract the data_source_id from the DB-create response.
// For single-source inline DBs this is what pages.create() inside the
// Fee Schedule needs as parent — not the database_id.
const db = $input.first().json;
const ds = (db.data_sources && db.data_sources[0] && db.data_sources[0].id) || db.id;
const briefId = $('Notion: new Brief').first().json.id;
const briefName = (($('Notion: new Brief').first().json.properties.Name.title[0] || {}).plain_text) || '';

const seeds = [
  { service: 'Schematic Design',              order: 1 },
  { service: 'Design Development',            order: 2 },
  { service: 'Construction Documents',        order: 3 },
  { service: 'Construction Administration',   order: 4 },
  { service: 'Special Structural Inspections',order: 5 },
  { service: 'Engineering Site Visits',       order: 6 },
];

return seeds.map(s => ({
  json: Object.assign({ ds_id: ds, brief_id: briefId, brief_name: briefName }, s),
}));

